typedef std::uint8_t  uint8;
typedef std::uint16_t uint16;
typedef std::uint32_t uint32;
typedef unsigned int  uint;

// Alignment-safe 16/32-bit load/store. The reference uses raw `*(uint32*)p` casts on
// a byte buffer, which is misaligned-access UB the -O3 build miscompiles (verified via
// UBSan). memcpy lowers to the same little-endian moves on x86 with no UB.
static inline uint16 Ld16(const uint8 *p) { uint16 v; std::memcpy(&v, p, 2); return v; }
static inline uint32 Ld32(const uint8 *p) { uint32 v; std::memcpy(&v, p, 4); return v; }
static inline void   St16(uint8 *p, uint16 v) { std::memcpy(p, &v, 2); }
static inline void   St32(uint8 *p, uint32 v) { std::memcpy(p, &v, 4); }

